    lines.length = 0;
  }
});

function getResult(nums, bag) {
  const n = nums.length;

  const dp = new Array(n + 1).fill(0).map(() => new Array(bag + 1).fill(0));
  dp[0][0] = 1;

  for (let i = 1; i <= n; i++) {
    const num = nums[i - 1];
    for (let j = 0; j <= bag; j++) {
      if (j < num) {
        dp[i][j] = dp[i - 1][j];
      } else {
        dp[i][j] = dp[i - 1][j] + dp[i - 1][j - num];
      }
    }
  }

  return dp[n][bag];
}

